const t=[{id:"cube-house",title:"Cube House",category:"Residential",location:"Gandhinagar, Gujarat",year:"2024",area:"2,200 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_2%20-%20Photo.jpg?updatedAt=1772272176314",overview:'"Cube House" is a striking modern residence defined by its bold, stacked rectilinear volumes and clean, minimalist lines. The exterior utilizes a balanced palette of smooth plaster, deeply textured dark grey cladding, and warm timber accents to create a commanding yet inviting street presence.',concept:"The core architectural concept revolves around the precise stacking and intersection of rigid cuboid forms to create dynamic spatial depth. By resting a heavier, darkly textured upper volume upon a lighter ground floor, the structure achieves a striking cantilevered effect that makes the top floor appear to float. The deep overhangs and carved-out balconies generated by this geometric arrangement serve a dual purpose, providing essential weather protection while functioning as sheltered transitional spaces between the indoors and the landscape.",images:["https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_1%20-%20Photo.jpg?updatedAt=1772272170070","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_3%20-%20Photo.jpg?updatedAt=1772272175468","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_4%20-%20Photo.jpg?updatedAt=1772272172192","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_5%20-%20Photo.jpg?updatedAt=1772272171479","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_6%20-%20Photo.jpg?updatedAt=1772272176414","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/CUBE%20HOUSE/1_7%20-%20Photo.jpg?updatedAt=1772272175904"],testimonial:{quote:"parArc Design Studio perfectly captured our vision for the Cube House, blending bold geometric lines with striking vertical textures to create beautiful, inviting spaces like our elegant balcony retreat.",author:"Sandip Patel",role:"Homeowner, Cube House"}},{id:"pararc-studio",title:"parArc Studio",category:"Interiors",location:"Gandhinagar, Gujarat",year:"2026",area:"200 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_112322.jpg",overview:"The creative workspace of parArc Design Studio, reflecting our own design philosophies of light, material integrity, and spatial fluidity.",concept:"Our studio workspace serves as a live gallery of our architectural ideals. Blending raw textured walls, custom steel partitions, and warm wooden accents, the layout is designed to foster creative collaboration. The space maximizes natural daylight and incorporates strategic green pockets to create a workspace that is both highly productive and deeply calming.",images:["https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_113013.jpg","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_112655.jpg","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_112824.jpg","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_112727.jpg","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/Pararc%20studio/20260525_112917.jpg"],testimonial:null},{id:"the-glaze",title:"The Glaze",category:"Commercial",location:"Chhatral, Gujarat",year:"2024",area:"12,000 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/1.png?updatedAt=1772271427823",overview:"The Glaze is a contemporary commercial office that prioritizes transparency and light. The design utilizes large expanses of glass and a minimal structural frame to create an open, vibrant workspace. The project represents parArc's approach to commercial design, where functionality is enhanced by a strong aesthetic identity and a focus on the well-being of the inhabitants.",concept:"The Glaze project strikes a balance between industrial robustness and professional elegance. The design features a clean, minimalist aesthetic with an emphasis on natural light and open-plan workspaces. The use of glass partitions and double-height spaces creates a sense of transparency and connectivity, reflecting the studio's commitment to creating functional yet inspiring work environments.",images:["https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/2.png?updatedAt=1772271428238","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/3.png?updatedAt=1772271428872","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/4.png?updatedAt=1772271428770","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/5.png?updatedAt=1772271429985","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/THE%20GLAZE/6.png?updatedAt=1772271429903"],testimonial:{quote:"parArc delivered a workspace that not only looks stunning but has significantly improved our team's daily synergy.",author:"Suraj Infrastructure",role:"Company, The Glaze"}},{id:"the-intersect",title:"The Intersect",category:"Residential",location:"Nandasan, Gujarat",year:"2025",area:"1,800 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_1%20-%20Photo.jpg?updatedAt=1772272030631",overview:'"The Intersect" is a contemporary residence defined by its bold geometric clarity and stark, rectilinear forms. The design utilizes a restrained palette of smooth finishes and deeply textured grey cladding to highlight the shifting volumes of the exterior. It stands as a striking modern structure that establishes a strong visual presence while harmonizing with its lush, organic surroundings.',concept:"The core architectural concept revolves around the seamless overlapping of distinct, heavy rectangular blocks. Rather than presenting as a single solid mass, the ground floor and upper level physically slide past one another, naturally generating deep overhangs and spacious open-air roof terraces. The prominent entrance canopy acts as the defining node where these strong horizontal slabs and vertical structural planes meet. Ultimately, this intentional intersection of mass and void creates a highly dynamic facade defined by shifting depths, layered materials, and sharp shadows.",images:["https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_2%20-%20Photo.jpg?updatedAt=1772272029873","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_3%20-%20Photo.jpg?updatedAt=1772272033257","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_5%20-%20Photo.jpg?updatedAt=1772272032041","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_6%20-%20Photo.jpg?updatedAt=1772272033482","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20INTERSECT/1_9%20-%20Photo.jpg?updatedAt=1772272031098"],testimonial:{quote:"parArc Design Studio delivered a stunning modern home, perfectly balancing bold geometric lines with warm wood accents and raw concrete textures.",author:"Bharat Patel",role:"Homeowner, The Intersect"}},{id:"the-framed-room",title:"The Framed Room",category:"Interiors",location:"Kalol, Gujarat",year:"2023",area:"430 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/1.png?updatedAt=1772272371661",overview:"A dynamic and creative workspace designed to inspire professional photography and artistic innovation.",concept:"The Framed Room project is a masterclass in functional minimalism and lighting control. The design includes a sophisticated reception area, comfortable client meeting zones, and state-of-the-art shooting spaces. A neutral color palette ensures that the focus remains on the creative work, while versatile furniture and modular layouts provide the flexibility required for various photographic setups. The integration of modern aesthetics with practical requirements creates a professional yet inspiring environment for creators.",images:["https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/2.png?updatedAt=1772272373295","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/3.png?updatedAt=1772272372890","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/4.png?updatedAt=1772272371411","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/5.png?updatedAt=1772272371019","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20FRAMED%20ROOM/6.png?updatedAt=1772272373686"],testimonial:{quote:"Thanks to parArc Design Studio's visionary layout and rich material choices, every corner of our studio acts as a stunning, perfectly lit backdrop for our shoots.",author:"Rushi Purohit",role:"Owner, The Framed Room"}},{id:"the-gilded-quarry",title:"The Gilded Quarry",category:"Interiors",location:"Kalol, Gujarat",year:"2025",area:"1,100 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20GILDED%20QUARRY/1.png?updatedAt=1772272311407",overview:"A stunning interior narrative that explores the intersection of raw stone textures and refined golden accents.",concept:"The Gilded Quarry is a celebration of material contrast and geological beauty. The design utilizes large-format stone surfaces paired with meticulously crafted metal details to create an atmosphere of grounded luxury. Every element is chosen to reflect light and shadow in a way that emphasizes the natural variations of the stone, while the golden accents provide a touch of warmth and modern sophistication. This project demonstrates how bold material choices can create a space that is both monumental and intimately comfortable.",images:["https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20GILDED%20QUARRY/2.png?updatedAt=1772272310977","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20GILDED%20QUARRY/3.png?updatedAt=1772272311374","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20GILDED%20QUARRY/4.png?updatedAt=1772272311304","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20GILDED%20QUARRY/5.png?updatedAt=1772272296825"],testimonial:{quote:"parArc Design Studio perfectly translated our vision of luxury into reality, blending rich textures and flawless lighting to create a truly breathtaking showroom.",author:"Vijay Patel",role:"Owner, The Gilded Quarry"}},{id:"the-woven-plaze",title:"The Woven Plaza",category:"Landscape",location:"Pundhra, Gujarat",year:"2023",area:"3136 sq yards",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_10%20-%20Photo.jpg?updatedAt=1772271511699",overview:"A multi-layered landscape designed to serve as a communal gathering space and a private retreat.",concept:"The Woven Plaza is conceptualized as a spatial tapestry where hardscapes and softscapes intertwine. The design focuses on creating a rhythmic flow between open plazas and intimate garden pockets. By using local materials and drought-resistant flora, the project maintains a low ecological footprint while providing a lush, inviting atmosphere for residents and guests alike. The project represents parArc's commitment to creating landscapes that are as functional as they are visually poetic.",images:["https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_6%20-%20Photo.jpg?updatedAt=1772271515027","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_8%20-%20Photo.jpg?updatedAt=1772271511122","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_10%20-%20Photo.jpg?updatedAt=1772271511699","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_15%20-%20Photo.jpg?updatedAt=1772271513001","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/PUNDHRA%20FARMHOUSE/1_16%20-%20Photo.jpg?updatedAt=1772271513909"],testimonial:{quote:"The landscape design transformed our outdoor space into an architectural garden that lives and breathes with the seasons.",author:"Hardik Patel",role:"Owner, The Woven Plaza"}},{id:"factory-shed",title:"Factory Shed",category:"Commercial",location:"Chhatral, Gujarat",year:"2024",area:"12,000 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/1.png?updatedAt=1772271329698",overview:"A large-scale industrial facility optimized for manufacturing excellence and structural integrity.",concept:"The Factory Shed project is an exercise in large-span structural engineering and functional spatial planning. The design focuses on maximizing clear heights and provides an unobstructed floor area to accommodate complex manufacturing processes. Innovative ventilation and daylighting strategies were integrated into the roof structure to ensure a comfortable and sustainable working environment, demonstrating that industrial utility can coexist with architectural quality.",images:["https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/2.png?updatedAt=1772271329661","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/3.png?updatedAt=1772271327721","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/4.png?updatedAt=1772271327228","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/5.png?updatedAt=1772271329734","https://ik.imagekit.io/StudioparArc/parArc/COMMERCIAL/FACTORY%20SHED/6.png?updatedAt=1772271302639"],testimonial:null},{id:"offset-towers",title:"The Offset Towers",category:"Residential",location:"Ahmedabad, Gujarat",year:"2022",area:"3,000 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/4.png?updatedAt=1772272085838",overview:"A vertical exploration of shifted planes and staggered volumes, creating a dynamic residential landmark.",concept:"The Offset Towers challenge traditional verticality by sliding floor plates and wall planes horizontally. This shifting creates a rhythmic facade of cantilevered terraces and deeply recessed openings, optimizing natural light and ventilation for every living unit while providing sheltered outdoor spaces.",images:["https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/2.png?updatedAt=1772272089114","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/3.png?updatedAt=1772272088141","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/4.png?updatedAt=1772272085838","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/5.png?updatedAt=1772272089060","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/OFFSET%20TOWERS/6.png?updatedAt=1772272085280"],testimonial:null},{id:"the-overhange-house",title:"The Overhange House",category:"Residential",location:"Ahmedabad, Gujarat",year:"2021",area:"2,800 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/1.png?updatedAt=1772271983217",overview:'"The Overhang House" is a modern farmhouse defined by its bold, raw concrete geometry and striking cantilevered volumes that stretch out toward the rolling landscape. Expansive floor-to-ceiling glazing breaks up the heavy structural forms, flooding the interiors with natural light while framing panoramic views of the surrounding agricultural fields. The A bold architectural statement that masterfully utilizes dramatic cantilevers to create deep, sheltered spaces and a striking silhouette.ccents and deep, functional rooflines creates a balanced aesthetic that feels both monumental and deeply rooted in its pastoral setting.',concept:"The Overhang House is defined by its namesake architectural feature—a series of prominent, intersecting planes that provide shade and character. The design prioritizes spatial connectivity, with a central double-height volume that link the social areas of the home. Passive design strategies, including stack ventilation and strategic shading, ensure a comfortable interior climate throughout the year, while the large overhangs protect the facade from the intense tropical sun.",images:["https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/2.png?updatedAt=1772271980429","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/3.png?updatedAt=1772271979303","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/4.png?updatedAt=1772271983268","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/5.png?updatedAt=1772271983579","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/6.png?updatedAt=1772271981028","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/7.png?updatedAt=1772271984462","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/8.png?updatedAt=1772271979319","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/9.png?updatedAt=1772271979178","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20OVERHANGE%20HOUSE/10.png?updatedAt=1772271977356"],testimonial:null},{id:"the-screen-house",title:"The Screen House",category:"Residential",location:"Kalol, Gujarat",year:"2023",area:"2,800 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_1%20-%20Photo.jpg?updatedAt=1772271866019",overview:'"The Screen House" presents a bold, contemporary composition defined by intersecting geometric volumes and striking, angular cantilevered forms in vibrant terracotta tones. The architectural massing contrasts solid, muted grey walls with expansive balconies, creating a A sophisticated play of light and shadow, using intricate screening to balance transparency with seclusion. of deep overhangs and layered facades ensures climate responsiveness while framing sweeping views of the surrounding farmhouse landscape.',concept:"The core design concept revolves around the extensive use of perforated lattice screens that wrap the exterior, acting as a breathable skin for the home. These screens masterfully filter harsh sunlight to create ever-changing shadow patterns indoors, while simultaneously ensuring natural ventilation and visual privacy. Ultimately, the design bridges the gap between intimate, secure living spaces and the expansive outdoors, seamlessly blending modern living with the natural environment.",images:["https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_2%20-%20Photo.jpg?updatedAt=1772271865099","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_3%20-%20Photo.jpg?updatedAt=1772271865775","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_4%20-%20Photo.jpg?updatedAt=1772271865524","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_5%20-%20Photo.jpg?updatedAt=1772271866003","https://ik.imagekit.io/StudioparArc/parArc/RESIDENCIAL%20/THE%20SCREEN%20HOUSE/1_7%20-%20Photo.jpg?updatedAt=1772271865977"],testimonial:{quote:"We are in love with the dynamic facade parArc Design Studio created; the custom perforated screens and layered geometry perfectly balance natural light and privacy.",author:"Maulik Patel",role:"Homeowner, The Screen House"}},{id:"the-pillar-path",title:"The Pillar Path",category:"Landscape",location:"Ahmedabad, India",year:"2024",area:"1,400 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_10%20-%20Photo.jpg?updatedAt=1772271584952",overview:"The Pillar Path is an exploration of verticality in the landscape. A series of sculptural pillars are used to define boundaries and create aSense of mystery. The path winds through a variety of planting zones—from structural hedges to wilder, meadow-like areas—providing a rich diversity of experiences within a modest footprint. The project demonstrates how architectural elements can be used to structure a garden and create a cohesive narrative between the home and its immediate surroundings.",concept:"The core design concept revolves around the rhythmic placement of glowing, pillar-like bollards that flank the walkway, acting as guiding beacons through the serene outdoor space. This deliberate interplay of ambient light, linear hardscaping, and carefully curated greenery creates a tranquil transition zone, transforming the approach into a calm, meditative journey.",images:["https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_3%20-%20Photo.jpg?updatedAt=1772271585809","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_4%20-%20Photo.jpg?updatedAt=1772271585849","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_5%20-%20Photo.jpg?updatedAt=1772271584558","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_10%20-%20Photo.jpg?updatedAt=1772271584952","https://ik.imagekit.io/StudioparArc/parArc/LANDSCAPE/VILLAGE%20HOME%20LANDSCAPE/1_11%20-%20Photo.jpg?updatedAt=1772271584881"],testimonial:null},{id:"the-terra-canvas",title:"The Terra Canvas",category:"Interiors",location:"Gandhinagar, India",year:"2024",area:"2,070 sq ft",heroImage:"https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/1.png?updatedAt=1772272268066",overview:"An earthy and textural home interior that brings the warmth of the natural world indoors.",concept:"The Terra Canvas project is an exploration of organic materiality and soothing color palettes. Inspired by the varied tones of the earth, the design incorporates clay textures, wooden elements, and soft linen fabrics to create a sanctuary of calm. Large windows allow natural light to play across the textured surfaces, revealing the depth and character of the materials used. The layout is open and inviting, encouraging a seamless flow between different living areas while maintaining a sense of rhythmic harmony throughout the home.",images:["https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/2.png?updatedAt=1772272267851","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/3.png?updatedAt=1772272253410","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/4.png?updatedAt=1772272265788","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/5.png?updatedAt=1772272266240","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/6.png?updatedAt=1772272251600","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/7.png?updatedAt=1772272267715","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/8.png?updatedAt=1772272239203","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/9.png?updatedAt=1772272266800","https://ik.imagekit.io/StudioparArc/parArc/INTERIOR/THE%20TERRA%20CANVAS/10.png?updatedAt=1772272267896"],testimonial:{quote:"parArc Design Studio completely transformed our apartment into a warm, modern sanctuary, perfectly balancing earthy wall textures, sleek custom cabinetry, and a beautifully open, light-filled layout.",author:"Parth Prajapati",role:"Homeowner, The Terra Canvas"}}];export{t as p};
